data.source:
erDiagram
    LEARNER ||--o{ ENROLLMENT : has
    COURSE ||--o{ ENROLLMENT : receives
    COURSE ||--|{ LESSON : contains
    LEARNER {
        int learner_id PK
        string name
    }
    COURSE {
        int course_id PK
        string title
    }
    ENROLLMENT {
        int learner_id FK
        int course_id FK
        string status
    }
    LESSON {
        int lesson_id PK
        int course_id FK
    }
